// Let's create a robust parser for the 12 dates on Google Flights
const datesToCheck = [
  { date: "2026-10-15", day: "Thu", type: "nonstop_day" },
  { date: "2026-10-24", day: "Sat", type: "nonstop_day" },
  { date: "2026-11-03", day: "Tue", type: "nonstop_day" },
  { date: "2026-11-12", day: "Thu", type: "nonstop_day" },
  { date: "2026-11-13", day: "Fri", type: "fallback_day" },
  { date: "2026-11-24", day: "Tue", type: "nonstop_day" },
  { date: "2026-12-05", day: "Sat", type: "nonstop_day" },
  { date: "2026-12-16", day: "Wed", type: "fallback_day" },
  { date: "2026-12-17", day: "Thu", type: "nonstop_day" },
  { date: "2027-01-14", day: "Thu", type: "nonstop_day" },
  { date: "2027-01-25", day: "Mon", type: "fallback_day" },
  { date: "2027-02-18", day: "Thu", type: "nonstop_day" }
];

const parsed12 = [];

for (const d of datesToCheck) {
  const url = `https://www.google.com/travel/flights?q=Flights%20from%20KUL%20to%20LBJ%20on%20${d.date}%20one%20way`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3500 });

  const pageInfo = await browserjs(tabId, () => {
    const text = document.body.innerText;
    // Extract flight sections
    // Let's find all flights listed
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    return { lines };
  });

  // Let's parse flight options from lines
  const lines = pageInfo.lines;
  const flights = [];

  // Find lines with time pattern: e.g. "10:45 AM" or similar
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].match(/^\d{1,2}:\d{2}\s*[AP]M$/i) && lines[i+1] === "–" && lines[i+2]?.match(/^\d{1,2}:\d{2}\s*[AP]M(\+\d)?$/i)) {
      const depTime = lines[i];
      const arrTime = lines[i+2];
      const airline = lines[i+3];
      const duration = lines[i+4];
      const route = lines[i+5]; // e.g. KUL–LBJ
      const stops = lines[i+6]; // Nonstop or 1 stop
      let stopDetail = "";
      let price = "";
      let idx = i + 7;
      if (stops === "1 stop" || stops.includes("stop")) {
        stopDetail = lines[idx]; // e.g. "9 hr 15 min DPS"
        idx++;
      }
      // scan ahead up to 10 lines for price ($...)
      for (let j = idx; j < Math.min(lines.length, idx + 8); j++) {
        if (lines[j].match(/^\$\d+$/)) {
          price = lines[j];
          break;
        }
      }
      flights.push({
        depTime,
        arrTime,
        airline,
        duration,
        stops,
        stopDetail,
        price
      });
    }
  }

  parsed12.push({
    date: d.date,
    day: d.day,
    type: d.type,
    flightCount: flights.length,
    flights
  });
}

await write("tmp://parsed_12_dates.json", JSON.stringify(parsed12, null, 2));
console.log("Parsed 12 dates summary:");
for (const p of parsed12) {
  console.log(`\n=== Date: ${p.date} (${p.day}) ===`);
  p.flights.forEach((f, idx) => {
    console.log(`  [${idx+1}] ${f.airline} | ${f.depTime} - ${f.arrTime} | ${f.duration} | ${f.stops} ${f.stopDetail} | ${f.price}`);
  });
}

